    [3070]={name="Ensign Cloak",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'Bounty on Garrick Padfoot'. Pick it over the other reward choices. Starts with Deputy Willem in Elwynn Forest. Objective: Kill Garrick Padfoot and bring his head to Deputy Willem at Northshire Abbey.",zone="Northshire Valley",questName="Bounty on Garrick Padfoot",lore="Garrick Padfoot - a cutthroat who's plagued our farmers and merchants for weeks - was seen at a shack near the vineyards, which lies east of the Abbey and across the bridge."},
    [3079]={name="Skorn's Rifle",quality=2,ilvl=12,sourceType="quest_reward",instructions="Reward from the quest 'The Demon Scarred Cloak'. Pick it over the other reward choices. The quest is in Mulgore. Objective: Find someone who knows of Ghost Howl. Provided item:.",zone="Mulgore",questName="The Demon Scarred Cloak",lore="The ragged hide of Ghost Howl still bears a terrible wound, gained from the wolf's battles against the Burning Legion. Perhaps someone in Bloodhoof Village should know of Ghost Howl's demise...."},
    [3152]={name="Driving Gloves",quality=1,ilvl=9,sourceType="quest_reward",instructions="Reward from the quest 'Operation Recombobulation'. Pick it over the other reward choices. Starts with Razzle Sprysprocket in Dun Morogh. Objective: Bring Razzle Sprysprocket in Kharanos 8 Restabilization Cogs and 8 Gyromechanic Gears.",zone="Dun Morogh",questName="Operation Recombobulation",lore="Upon further analysis of the Gnomeregan situation, it would appear as though we not only failed to eradicate the troggs but we also happened to turn most of the gnomish race into horrific, mindless, evil-doing leper gnomes."},
    [3153]={name="Oil-stained Cloak",quality=1,ilvl=9,sourceType="quest_reward",instructions="Reward from the quest 'Operation Recombobulation'. Pick it over the other reward choices. Starts with Razzle Sprysprocket in Dun Morogh. Objective: Bring Razzle Sprysprocket in Kharanos 8 Restabilization Cogs and 8 Gyromechanic Gears.",zone="Dun Morogh",questName="Operation Recombobulation",lore="Upon further analysis of the Gnomeregan situation, it would appear as though we not only failed to eradicate the troggs but we also happened to turn most of the gnomish race into horrific, mindless, evil-doing leper gnomes."},
