    [3277]={name="Executor Staff",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'The Red Messenger'. Pick it over the other reward choices. Starts with Executor Arren in Tirisfal Glades. Objective: Kill Meven Korgal, the messenger, at the Crusader camp, then return any information you find to Executor Arren.",zone="Deathknell",questName="The Red Messenger",lore="Reports from my superiors in Brill indicate that an agent of the Scarlet Crusade was dispatched from the Scarlet Monastery and sent here to Deathknell."},
