    [3435]={name="Zombie Skin Bracers",quality=1,ilvl=8,sourceType="quest_reward",instructions="Reward from the quest 'Proof of Demise'. Pick it over the other reward choices. Starts with Deathguard Burgess in Tirisfal Glades. Objective: Bring 10 Scarlet Insignia Rings to Deathguard Burgess in Brill.",zone="Tirisfal Glades",questName="Proof of Demise",lore="Executor Zygand tells me you've been out killing Scarlet Crusaders. Tirisfal Glades is crawling with them."},
    [3439]={name="Zombie Skin Boots",quality=1,ilvl=8,sourceType="quest_reward",instructions="Reward from the quest 'Graverobbers'. Pick it over the other reward choices. Starts with Magistrate Sevren in Tirisfal Glades. Objective: Kill Rot Hide Graverobbers and Rot Hide Mongrels. Bring 8 Embalming Ichors to Magistrate Sevren in Brill.",zone="Tirisfal Glades",questName="Graverobbers",lore="The Mass Graves, southwest of Garren's Haunt to the north, were made to accommodate the...impressive...number of deaths Tirisfal suffered when the Plague first came."},
    [3443]={name="Ceremonial Tomahawk",quality=1,ilvl=10,sourceType="quest_reward",instructions="Reward from the quest 'Wildmane Cleansing'. Pick it over the other reward choices. Starts with Mull Thunderhorn in Mulgore. Objective: Use the Wildmane Cleansing Totem at the Wildmane Water Well, then return to Mull Thunderhorn.",zone="Mulgore",questName="Wildmane Cleansing",lore="Your cleansing of the Winterhoof and Thunderhorn wells is spoken among the spirits, young. The Wildmane Totem is made, and your last task lies ahead."},
    [3444]={name="Tiller's Vest",quality=1,ilvl=11,sourceType="quest_reward",instructions="Reward from the quest 'Wanted: Maggot Eye'. Pick it over the other reward choices. The quest is in Tirisfal Glades. Objective: Kill Maggot Eye and return to Executor Zygand in Brill with his paw for a reward.",zone="Tirisfal Glades",questName="Wanted: Maggot Eye",lore="Wanted: Maggot Eye! A foul beast, even by Gnoll standards, Maggot Eye has been sentenced to death for his crimes against The Forsaken. This despicable villain has been stealing corpses for use by the Lich King's army."},
    [3446]={name="Darkwood Staff",quality=2,ilvl=13,sourceType="quest_reward",instructions="Reward from the quest 'The Family Crypt'. Pick it over the other reward choices. Starts with Magistrate Sevren in Tirisfal Glades. Objective: Kill 8 Wailing Ancestors and 8 Rotting Ancestors.Kill Captain Dargol, and bring his skull to Magistrate Sevren in Brill.",zone="Tirisfal Glades",questName="The Family Crypt",lore="The Agamand Mills area has become a foothold for the Scourge. Their strongest point is the Agamand Family Crypt where their local military leader, a skeleton named Captain Dargol, has headquartered."},
