    [3833]={name="Adept's Cloak",quality=1,ilvl=8,sourceType="quest_reward",instructions="Reward from the quest 'The Chill of Death'. Pick it over the other reward choices. Starts with Gretchen Dedmar in Tirisfal Glades. Objective: Bring five Duskbat Pelts and some Coarse Thread to Gretchen Dedmar in Brill.",zone="Tirisfal Glades",questName="The Chill of Death",lore="It's so cold, now. The Plague of Undeath crawls through my veins like an icy serpent. The Mindless State will be upon me soon. But no doomed destiny will prevent me from serving our Dark Lady."},
