    [10547]={name="Camping Knife",quality=1,ilvl=8,sourceType="quest_reward",instructions="Reward from the quest 'Return to Bellowfiz'. Pick it over the other reward choices. Starts with Rejold Barleybrew in Dun Morogh. Objective: Give the cask of Evershine to Pilot Bellowfiz at Steelgrill's Depot.",zone="Dun Morogh",questName="Return to Bellowfiz",lore="Here's your cask of Evershine. And again, thank you for the hunting earlier."},
    [10549]={name="Rancher's Trousers",quality=2,ilvl=12,sourceType="quest_reward",instructions="Reward from the quest 'Protecting the Herd'. Pick it over the other reward choices. Starts with Rudra Amberstill in Dun Morogh. Objective: Rudra Amberstill wants you to slay Vagash and bring his fang to her at the Ram ranch.",zone="Dun Morogh",questName="Protecting the Herd",lore="We heard the cries in the middle of the night. Then this morning, sure enough, the herd was missing two rams. That dastardly beast known as Vagash has been preying on our livelihood."},
    [10553]={name="Foreman Vest",quality=2,ilvl=11,reqLevel=6,sourceType="world_drop",instructions="Drops from Gibblewilt (rare spawn).",zone="Brewnall Village",npc="Gibblewilt"},
