    [10636]={name="Nomadic Gloves",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'Break Sharptusk!'. Pick it over the other reward choices. Starts with Brave Windfeather in Mulgore. Objective: Bring the head of Chief Sharptusk Thornmantle to Brave Windfeather in Red Cloud Mesa.",zone="Red Cloud Mesa",questName="Break Sharptusk!",lore="- I have heard of you, newcomer. Perhaps it is you that will help us, where others have failed. We tauren have carved a home out of this land, but not without a cost."},
    [11187]={name="Stemleaf Bracers",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'The Balance of Nature'. Pick it over the other reward choices. Starts with Conservator Ilthalaine in Teldrassil. Objective: Kill 7 Young Nightsabers and 4 Young Thistle Boars and return to Conservator Ilthalaine.",zone="Shadowglen",questName="The Balance of Nature",lore="Greetings. I am Conservator Ilthalaine. My purpose in Shadowglen is to ensure that the balance of nature is maintained."},
    [11189]={name="Woodland Robes",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'Webwood Egg'. Pick it over the other reward choices. Starts with Gilshalan Windwalker in Teldrassil. Objective: Bring a Webwood Egg to Gilshalan in Aldrassil.",zone="Shadowglen",questName="Webwood Egg",lore="Now that I have the spiders' venom, I'd like some live specimens to study. Unfortunately, capturing a living, giant spider is more than I can ask of you, young."},
    [11190]={name="Viny Gloves",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'The Woodland Protector'. Pick it over the other reward choices. Starts with Tarindrella in Teldrassil. Objective: Collect 8 Fel Moss and bring them to Tarindrella.",zone="Shadowglen",questName="The Woodland Protector",lore="Something evil is brewing in the forests of Teldrassil. Look long the hills to where the peaceful furbolgs used to dwell. They have deserted their homes and are amassing under the name of the Gnarlpine tribe."},
    [11192]={name="Outfitter Gloves",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'Skirmish at Echo Ridge'. Pick it over the other reward choices. Starts with Marshal McBride in Elwynn Forest. Objective: Kill 12 Kobold Laborers, then return to Marshal McBride at Northshire Abbey.",zone="Northshire Valley",questName="Skirmish at Echo Ridge",lore="Your previous investigations are proof that the Echo Ridge Mine needs purging. Return to the mine and help clear it of kobolds. Waste no time."},
    [11475]={name="Wine-stained Cloak",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'Grape Manifest'. Pick it over the other reward choices. Starts with Milly Osworth in Elwynn Forest. Objective: Bring the Grape Manifest to Brother Neals in Northshire Abbey.",zone="Northshire Valley",questName="Grape Manifest",lore="You'll find Brother Neals in the abbey, in the bell tower... where he likes to taste his wine."},
    [11848]={name="Flax Belt",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'Scavenging Deathknell'. Pick it over the other reward choices. Starts with Deathguard Saltain in Tirisfal Glades. Objective: Search Deathknell and the vicinity for 6 pieces of Scavenged Goods, and return them to Deathguard Saltain.",zone="Deathknell",questName="Scavenging Deathknell",lore="You there! If you're looking for something to make yourself useful, then listen up! We need fresh out-of-the-ground recruits to head into Deathknell and search for any sort of useful equipment."},
    [11850]={name="Short Duskbat Cape",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'Scavenging Deathknell'. Pick it over the other reward choices. Starts with Deathguard Saltain in Tirisfal Glades. Objective: Search Deathknell and the vicinity for 6 pieces of Scavenged Goods, and return them to Deathguard Saltain.",zone="Deathknell",questName="Scavenging Deathknell",lore="You there! If you're looking for something to make yourself useful, then listen up! We need fresh out-of-the-ground recruits to head into Deathknell and search for any sort of useful equipment."},
