    [23323]={name="Crown of the Fire Festival",quality=1,ilvl=1,sourceType="seasonal_quest",instructions="Reward from the quest 'A Thief's Reward'. Objective: Return the Flame of Stormwind to (NAME). A Midsummer quest. Rewards Crown of the Fire Festival. Added in Classic World of Warcraft. Always up to date.",questName="A Thief's Reward",lore="This flame, stolen from the heart of Stormwind itself, floods you with warmth. This raw power is foreign to you, but the (NAME) might know more..."},
    [23324]={name="Mantle of the Fire Festival",quality=1,ilvl=1,sourceType="seasonal_quest",instructions="Reward from the quest 'Wild Fires in the Eastern Kingdoms'. Starts with Festival Flamekeeper in Undercity. Objective: Visit the Fire Festival camps located in Blasted Lands, Eastern Plaguelands, the Hinterlands and Searing Gorge, then speak with the Festival Flamekeeper.",zone="Undercity",questName="Wild Fires in the Eastern Kingdoms",lore="Our celebration of the flame is spread throughout the land. Not a single place remains untouched by the heat of this holiday, and the strongest fires burn a brilliant blue."},
